css:
.details-table {
    width: 100%;
    border-collapse: collapse;
}

.details-table td {
    padding: 3px 0;
    border: none;
}

.ref-label {
    width : 80px;
    text-align: left;
}

.ref-value {
    text-align: left;
    padding-left: 20px !important;
}

.ref-date {
    text-align: right;
    white-space: nowrap;
}
.pricing-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
}

.pricing-table th,
.pricing-table td {
    border: 1px solid #000;
    padding: 4px 5px;
    vertical-align: middle;
}

.pricing-table th {
    text-align: center;
    line-height: 1.15;
}

.system-description div {
    line-height: 1.3;
}

.amount {
    text-align: right;
    white-space: nowrap;
}

.section-title {
    padding: 10px 0px;
    font-weight: bold
}

.kseb-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9.5pt;
}

.kseb-table th,
.kseb-table td {
    border: 1px solid #000;
    padding: 5px 10px;
    vertical-align: top;
}

.kseb-table ol {
    margin: 0 !important;
    padding-left: 20px !important;
}

.kseb-table li {
    margin: 0 !important;
    padding: 0 !important;
}

ul {
    margin: 0 !important;
    padding-left: 0 !important;
    list-style-position: inside;
}

li {
    margin: 0 !important;
    padding: 0 !important;
}

.bom-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10.5pt;
}

.bom-table th,
.bom-table td {
    border: 1px solid #000;
    padding: 4px 6px;
    vertical-align: middle;
}

.bom-table th {
    text-align: center;
    font-weight: bold;
}

.bom-table td:first-child,
.bom-table td:last-child {
    text-align: center;
}
.proposal-closing {
    page-break-inside: avoid;
}
.signature {
    width: 280px;
    margin-left: auto;
    text-align: left;
    margin-top: 30px;
}
